:root {
  color-scheme: light;
  --background: #f5f7fb;
  --surface: #ffffff;
  --ink: #172033;
  --muted: #68738a;
  --line: #dce2ec;
  --accent: #4857d6;
  --accent-dark: #3543b5;
  --danger: #b42318;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  color: var(--ink);
  background: var(--background);
}

button,
input,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.project-page {
  width: min(1120px, calc(100% - 32px));
  margin: 0 auto;
  padding: 48px 0 64px;
}

.page-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
}

.eyebrow {
  margin: 0 0 8px;
  color: var(--accent);
  font-size: .75rem;
  font-weight: 750;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 8px;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1;
}

h2 {
  font-size: 1.2rem;
}

.page-description {
  margin-bottom: 0;
  color: var(--muted);
}

.button {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 10px 16px;
  font-weight: 650;
  transition: background .15s ease, border-color .15s ease;
}

.button-primary {
  color: #fff;
  background: var(--accent);
}

.button-primary:hover {
  background: var(--accent-dark);
}

.button-secondary {
  color: var(--ink);
  background: var(--surface);
  border-color: var(--line);
}

.project-form-region,
.project-controls,
.project-columns {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.project-form-region {
  margin-bottom: 20px;
  padding: 24px;
}

.project-form-region[hidden],
.state-message[hidden] {
  display: none;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

label {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: .85rem;
  font-weight: 650;
}

input,
select {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 10px 12px;
  color: var(--ink);
  background: #fff;
}

input:focus,
select:focus {
  outline: 3px solid rgba(72, 87, 214, .18);
  border-color: var(--accent);
}

.form-field-wide {
  grid-column: 1 / -1;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 22px;
}

.project-controls {
  display: flex;
  gap: 16px;
  margin-bottom: 20px;
  padding: 16px;
}

.project-controls label:first-child {
  flex: 1;
}

.state-region {
  min-height: 0;
}

.state-message {
  padding: 20px;
  color: var(--muted);
  text-align: center;
}

.state-error {
  color: var(--danger);
}

.project-columns {
  min-height: 220px;
  padding: 20px;
}

.project-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 16px;
}

.project-card {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
}

.project-card h2 {
  margin: 0 0 8px;
}

.project-card p {
  color: var(--muted);
}

.project-meta {
  font-size: .9rem;
}

@media (max-width: 640px) {
  .project-page {
    padding-top: 28px;
  }

  .page-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .form-grid,
  .project-controls {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .form-field-wide {
    grid-column: auto;
  }

  .form-actions {
    justify-content: stretch;
  }

  .form-actions .button {
    flex: 1;
  }
}

